Snake: a grid, a body, food, and arrow-key direction. Each tick moves the head, grows on food, resets on a wall.
```html
<canvas id=g width=400 height=400></canvas>
<script>
c=g.getContext('2d');s=[[9,9]];d=[1,0];f=[5,5];
onkeydown=e=>{v=e.key;if(v=='ArrowUp'&&d[1]==0)d=[0,-1];if(v=='ArrowDown'&&d[1]==0)d=[0,1];
if(v=='ArrowLeft'&&d[0]==0)d=[-1,0];if(v=='ArrowRight'&&d[0]==0)d=[1,0]};
setInterval(()=>{h=[s[0][0]+d[0],s[0][1]+d[1]];
if(h[0]<0||h[0]>19||h[1]<0||h[1]>19){s=[[9,9]];return}
s.unshift(h);h[0]==f[0]&&h[1]==f[1]?f=[0|Math.random()*20,0|Math.random()*20]:s.pop();
c.fillStyle='#111';c.fillRect(0,0,400,400);c.fillStyle='#3fb950';
for(p of s)c.fillRect(p[0]*20,p[1]*20,19,19);c.fillStyle='#f85149';c.fillRect(f[0]*20,f[1]*20,19,19)},120);
</script>
```
Arrow keys steer; food grows the snake; a wall hit resets it.

Pong: two paddles, a ball, and keys. The ball bounces off walls and paddles and resets when it passes one.
```html
<canvas id=p width=600 height=400></canvas>
<script>
c=p.getContext('2d');b={x:300,y:200,dx:3,dy:2};L=160;R=160;k={};
onkeydown=e=>k[e.key]=1;onkeyup=e=>k[e.key]=0;
setInterval(()=>{if(k.w)L=Math.max(0,L-6);if(k.s)L=Math.min(320,L+6);
if(k.ArrowUp)R=Math.max(0,R-6);if(k.ArrowDown)R=Math.min(320,R+6);
b.x+=b.dx;b.y+=b.dy;if(b.y<0||b.y>390)b.dy*=-1;
if(b.x<20&&b.y>L&&b.y<L+80)b.dx=3;if(b.x>570&&b.y>R&&b.y<R+80)b.dx=-3;
if(b.x<0||b.x>600)b={x:300,y:200,dx:-b.dx,dy:2};
c.fillStyle='#111';c.fillRect(0,0,600,400);c.fillStyle='#eee';
c.fillRect(10,L,10,80);c.fillRect(580,R,10,80);c.beginPath();c.arc(b.x,b.y,6,0,7);c.fill()},16);
</script>
```
W and S move the left paddle; arrow keys move the right one.

A Three.js platformer: flat camera, boxes for the player and the floor, and gravity that resets on landing.
```html
<script type=module>
import * as T from 'https://unpkg.com/three@0.160.0/build/three.module.js';
sc=new T.Scene();cam=new T.PerspectiveCamera(60,innerWidth/innerHeight,.1,100);cam.position.z=14;
rn=new T.WebGLRenderer();rn.setSize(innerWidth,innerHeight);document.body.append(rn.domElement);
pl=new T.Mesh(new T.BoxGeometry(1,1,1),new T.MeshBasicMaterial({color:0x58a6ff}));sc.add(pl);
fl=new T.Mesh(new T.BoxGeometry(12,.6,1),new T.MeshBasicMaterial({color:0x3fb950}));fl.position.y=-3;sc.add(fl);
vy=0;g=0;k={};onkeydown=e=>k[e.key]=1;onkeyup=e=>k[e.key]=0;
(function t(){if(k.ArrowLeft)pl.position.x-=.15;if(k.ArrowRight)pl.position.x+=.15;
if(k[' ']&&g){vy=.22;g=0}vy-=.012;pl.position.y+=vy;g=0;
d=pl.position.y-.8-fl.position.y;
if(Math.abs(pl.position.x)<6.5&&d<0&&d>-.3&&vy<=0){pl.position.y=fl.position.y+.8;vy=0;g=1}
rn.render(sc,cam);requestAnimationFrame(t)})();
</script>
```

Attach a listener to the button and update the page inside it.
```js
const button = document.querySelector('#go');
const out = document.querySelector('#out');
button.addEventListener('click', () => {
  out.textContent = 'clicked ' + (Number(out.dataset.count || 0) + 1) + ' times';
  out.dataset.count = Number(out.dataset.count || 0) + 1;
});
```
Each click increments a counter stored on the element and writes the new total.

A game page needs a canvas, a score display, and a script tag.
```html
<!doctype html>
<html>
<head><meta charset="utf-8"><title>Game</title>
<style>body{margin:0;background:#111;color:#eee;font-family:monospace}
canvas{display:block;margin:0 auto;background:#000}</style></head>
<body>
<p id="score">Score: 0</p>
<canvas id="game" width="480" height="320"></canvas>
<script>
const ctx = document.getElementById('game').getContext('2d');
let score = 0;
function draw() {
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, 480, 320);
  ctx.fillStyle = '#3fb950'; ctx.fillRect(220, 140, 40, 40);
  document.getElementById('score').textContent = 'Score: ' + score;
  requestAnimationFrame(draw);
}
draw();
</script>
</body>
</html>
```
This draws a green square every frame and shows a score that you can increment from game logic.

